# AURORA A1 drawing set (TechDraw, A3). Run inside FreeCAD GUI after build_aurora_a1.build().
# Each sheet is generated by its own function so a caller can stay under GUI-dispatch time limits.
import os
import time
import FreeCAD as App
import TechDraw
from FreeCAD import Vector as V

import build_aurora_a1 as A

TPL = App.getResourceDir() + "Mod/TechDraw/Templates/ISO/A3_Landscape_TD.svg"
OUT = "C:/Prj/FreeCAD_Demo_001/aurora_a1/drawings"
DATE = "2026-09-26"
JP_FONT = "Yu Gothic"
TOTAL_SHEETS = 11

TOP = (V(0, 0, 1), V(1, 0, 0))        # plan, nose to the left
SIDE = (V(0, -1, 0), V(1, 0, 0))      # right-hand elevation, nose to the left
FRONT = (V(-1, 0, 0), V(0, -1, 0))    # looking at the nose
REAR = (V(1, 0, 0), V(0, 1, 0))
ISO = (V(-1, -1, 0.8), V(0.7071, -0.7071, 0))


def _pump(objs, timeout=75.0):
    """TechDraw projects in worker threads; spin the Qt loop until every view has edges."""
    from PySide import QtWidgets
    t0 = time.time()
    pending = [o for o in objs if o.isDerivedFrom("TechDraw::DrawViewPart")]
    while pending and time.time() - t0 < timeout:
        QtWidgets.QApplication.processEvents()
        time.sleep(0.03)
        pending = [o for o in pending if len(o.getVisibleEdges()) == 0]
    return [o.Name for o in pending]


def objs(doc, names):
    return [doc.getObject(n) for n in names if doc.getObject(n) is not None]


def by_prefix(doc, *prefixes):
    return [o for o in doc.Objects if o.TypeId == "Part::Feature" and o.Name.startswith(prefixes)]


class Sheet:
    def __init__(self, doc, key, title, subtitle, number, scale_txt):
        self.doc = doc
        self.key = key
        self.number = number
        self._remove_existing()
        self.page = doc.addObject("TechDraw::DrawPage", key)
        self.tpl = doc.addObject("TechDraw::DrawSVGTemplate", key + "_Tpl")
        self.tpl.Template = TPL
        self.page.Template = self.tpl
        texts = self.tpl.EditableTexts
        vals = {"FC-Title": title, "Subtitle": subtitle, "drawing_number": "AUR-A1-%02d" % number,
                "scale": scale_txt, "AuthorName": "Claude Code (FreeCAD MCP)", "CreationDate": DATE,
                "SheetNumber": "%d / %d" % (number, TOTAL_SHEETS), "SupervisorName": "-",
                "CheckDate": "-", "Weight": "-"}
        for k, v in vals.items():
            if k in texts:
                texts[k] = v
        self.tpl.EditableTexts = texts
        self.views = []
        self.dims = []

    def _remove_existing(self):
        old = self.doc.getObject(self.key)
        if old is not None:
            _close_page_window(old)
            # removing a view also removes its dimensions, so work from names
            names = [v.Name for v in old.Views]
            tpl_name = old.Template.Name if old.Template is not None else None
            for n in names:
                if self.doc.getObject(n) is not None:
                    self.doc.removeObject(n)
            self.doc.removeObject(old.Name)
            if tpl_name and self.doc.getObject(tpl_name) is not None:
                self.doc.removeObject(tpl_name)

    def view(self, name, sources, dirs, scale, x, y, caption="", coarse=False):
        v = self.doc.addObject("TechDraw::DrawViewPart", self.key + "_" + name)
        v.CoarseView = coarse
        self.page.addView(v)
        v.Source = sources
        v.Direction, v.XDirection = dirs
        v.ScaleType = "Custom"
        v.Scale = scale
        v.X, v.Y = x, y
        v.Caption = caption
        self.views.append(v)
        return v

    def section(self, name, base, symbol, normal, origin, dirs, scale, x, y, sources=None):
        s = self.doc.addObject("TechDraw::DrawViewSection", self.key + "_" + name)
        self.page.addView(s)
        s.BaseView = base
        s.Source = sources if sources is not None else base.Source
        s.SectionNormal = normal
        s.SectionOrigin = origin
        s.Direction, s.XDirection = dirs
        s.SectionSymbol = symbol
        s.Caption = "断面 %s-%s" % (symbol, symbol)
        s.ScaleType = "Custom"
        s.Scale = scale
        s.X, s.Y = x, y
        self.views.append(s)
        return s

    def note(self, name, lines, x, y, size=3.5):
        a = self.doc.addObject("TechDraw::DrawViewAnnotation", self.key + "_" + name)
        self.page.addView(a)
        a.Text = lines
        a.Font = JP_FONT
        a.TextSize = size
        a.X, a.Y = x, y
        return a

    def compute(self, deadline=900.0):
        """Generator: recompute, then yield 'waiting' until every projection has edges.
        HLR runs in worker threads, so the caller can return to FreeCAD between yields."""
        self.doc.recompute()
        t0 = time.time()
        while time.time() - t0 < deadline:
            pending = [v for v in self.views if v.isDerivedFrom("TechDraw::DrawViewPart")
                       and len(v.getVisibleEdges()) == 0]
            if not pending:
                return []
            yield "waiting"
        return [v.Name for v in pending]

    # ---- dimensions (called after compute); placed outside the view outline ----
    def extent(self, view, horizontal=True, side=None, gap=7.0):
        d = TechDraw.makeExtentDim(view, [], 0 if horizontal else 1)
        d.FormatSpec = "%.0f"
        x0, x1, y0, y1 = _extents(view)
        if horizontal:
            d.X, d.Y = (x0 + x1) / 2, (y0 - gap) if side == "below" else (y1 + gap)
        else:
            d.X, d.Y = (x1 + gap) if side == "right" else (x0 - gap), (y0 + y1) / 2
        self.dims.append(d)
        return d

    def dist(self, view, kind, p1, p2, offset=-12.0):
        """Length dimension between two 3D model points; offset is mm beyond the outline."""
        a, b = _to_view(view, p1), _to_view(view, p2)
        d = TechDraw.makeDistanceDim(view, kind, a, b)
        d.FormatSpec = "%.1f" if abs(round(d.getRawValue()) - d.getRawValue()) > 0.05 else "%.0f"
        x0, x1, y0, y1 = _extents(view)
        if kind == "DistanceX":
            d.X, d.Y = (a.x + b.x) / 2, (y0 + offset) if offset < 0 else (y1 + offset)
        else:
            d.X, d.Y = (x0 + offset) if offset < 0 else (x1 + offset), (a.y + b.y) / 2
        self.dims.append(d)
        return d

    def export(self):
        import FreeCADGui as Gui
        import TechDrawGui
        self.doc.recompute()
        _pump(self.views, 20)
        # the template is only put into the page scene once the page window exists
        self.page.ViewObject.show()
        from PySide import QtWidgets
        for _ in range(30):
            QtWidgets.QApplication.processEvents()
            time.sleep(0.02)
        os.makedirs(OUT, exist_ok=True)
        path = os.path.join(OUT, "%02d_%s.pdf" % (self.number, self.key))
        TechDrawGui.exportPageAsPdf(self.page, path)
        try:
            TechDraw.writeDXFPage(self.page, path[:-4] + ".dxf")
        except Exception as ex:
            print("dxf failed", self.key, ex)
        _close_page_window(self.page)
        return path


def _to_view(view, p):
    """3D model point -> scaled 2D point in the view's centred coordinate frame."""
    d = view.Direction.normalize()
    xd = view.XDirection.normalize()
    yd = d.cross(xd)
    c = _centroid(view)
    q = p - c
    return V(q.dot(xd) * view.Scale, q.dot(yd) * view.Scale, 0)


def _extents(view):
    """Scaled 2D bounds of the view's sources (bbox corners projected)."""
    import Part
    bb = App.BoundBox()
    for o in view.Source:
        bb.add(o.Shape.BoundBox)
    pts = [_to_view(view, V(x, y, z)) for x in (bb.XMin, bb.XMax) for y in (bb.YMin, bb.YMax)
           for z in (bb.ZMin, bb.ZMax)]
    return (min(p.x for p in pts), max(p.x for p in pts), min(p.y for p in pts), max(p.y for p in pts))


def _close_page_window(page):
    import FreeCADGui as Gui
    mw = Gui.getMainWindow()
    from PySide import QtWidgets
    mdi = mw.findChild(QtWidgets.QMdiArea)
    if mdi is None:
        return
    for w in mdi.subWindowList():
        if w.windowTitle().startswith(page.Label):
            w.close()


def _centroid(view):
    shapes = [o.Shape for o in view.Source]
    comp = shapes[0] if len(shapes) == 1 else __import__("Part").makeCompound(shapes)
    return TechDraw.findCentroid(comp, view.Direction)


