    body = [o for o in allp if not o.Name.startswith("Decal")]
    top = s.view("Top", body, TOP, 0.04, 150, 215, "上面図 TOP")
    side = s.view("Side", body, SIDE, 0.04, 150, 115, "側面図 SIDE")
    front = s.view("Front", body, FRONT, 0.04, 340, 215, "正面図 FRONT")
    iso = s.view("Iso", body, ISO, 0.025, 340, 125, "アイソメ ISO")
