def build_bom_sheet(doc):
    """Spreadsheet of every part's bounding-box size; shown on sheets 10-11."""
    sh = doc.getObject("BOM")
    if sh is None:
        sh = doc.addObject("Spreadsheet::Sheet", "BOM")
    sh.clearAll()
    rows = []
    for o in doc.Objects:
        if o.TypeId != "Part::Feature":
            continue
        grp = next((p.Name for p in o.InListRecursive if p.TypeId == "App::Part" and p.Name != "AURORA_A1_Assembly"
                    and not p.Name.startswith("Wheel_")), "")
        bb = o.Shape.BoundBox
        rows.append((grp, o.Name, bb.XLength, bb.YLength, bb.ZLength, o.Shape.Volume / 1000.0))
    order = ["Chassis", "Aerodynamics", "PowerUnit", "Drivetrain", "Suspension", "Wheels", "Livery"]
    rows.sort(key=lambda r: (order.index(r[0]) if r[0] in order else 99, r[1]))
    head = ["No.", "Group", "Part", "L (X)", "W (Y)", "H (Z)", "Vol cm3"]
    for c, h in zip("ABCDEFG", head):
        sh.set(c + "1", h)
    for i, r in enumerate(rows, 2):
        sh.set("A%d" % i, str(i - 1))
        sh.set("B%d" % i, r[0])
        sh.set("C%d" % i, r[1])
        sh.set("D%d" % i, "%.0f" % r[2])
        sh.set("E%d" % i, "%.0f" % r[3])
        sh.set("F%d" % i, "%.0f" % r[4])
        sh.set("G%d" % i, "%.0f" % r[5])
    doc.recompute()
    return sh, len(rows)


def sheet_bom(doc, part):
    sh, n = build_bom_sheet(doc)
    half = (n + 1) // 2
    r0, r1 = (2, half + 1) if part == 1 else (half + 2, n + 1)
    # each page gets its own sheet (header + its rows) so the header repeats cleanly
    name = "BOM_%d" % part
    page_sheet = doc.getObject(name) or doc.addObject("Spreadsheet::Sheet", name)
    page_sheet.clearAll()
    for c in "ABCDEFG":
        page_sheet.set(c + "1", sh.getContents(c + "1"))
    for out_r, src_r in enumerate(range(r0, r1 + 1), 2):
        for c in "ABCDEFG":
            page_sheet.set("%s%d" % (c, out_r), sh.getContents("%s%d" % (c, src_r)))
    s = Sheet(doc, "S%02d_BOM%d" % (9 + part, part), "部品表 (%d/2)" % part,
              "Parts list: bounding box mm / volume", 9 + part, "-")
    tv = doc.addObject("TechDraw::DrawViewSpreadsheet", s.key + "_Table")
    s.page.addView(tv)
    tv.Source = page_sheet
    tv.CellStart = "A1"
    tv.CellEnd = "G%d" % (r1 - r0 + 2)
    for col, w in zip("ABCDEFG", (40, 110, 230, 70, 70, 70, 90)):
        page_sheet.setColumnWidth(col, w)
    tv.TextSize = 11.0
    tv.Scale = 0.62
    tv.X, tv.Y = 160, 165
    s.doc.recompute()
    if False:
        yield
    return s


def sheet_bom1(doc):
    return (yield from sheet_bom(doc, 1))


def sheet_bom2(doc):
    return (yield from sheet_bom(doc, 2))


SHEETS = [sheet_ga, sheet_section_cl, sheet_front_wing, sheet_rear_wing, sheet_chassis, sheet_bodywork,
          sheet_wheels, sheet_suspension, sheet_powerunit, sheet_bom1, sheet_bom2]
_JOBS = {}


def step(i, budget=60.0):
    """Advance sheet i for at most `budget` seconds of GUI time; call again until it reports done.
    Between calls FreeCAD's worker threads keep computing the projections."""
    from PySide import QtWidgets
    doc = App.getDocument(A.DOC_NAME)
    job = _JOBS.get(i)
    if job is None:
        job = _JOBS[i] = {"gen": SHEETS[i](doc), "t0": time.time()}
    t = time.time()
    try:
        while time.time() - t < budget:
            if next(job["gen"]) == "waiting":
                QtWidgets.QApplication.processEvents()
                time.sleep(0.05)
    except StopIteration as done:
        del _JOBS[i]
        s = done.value
        path = s.export()
        return {"sheet": s.key, "pdf": path, "sec": round(time.time() - job["t0"], 1), "done": True}
    return {"sheet": i, "done": False, "elapsed": round(time.time() - job["t0"], 1)}


def run(i):
    r = step(i, 80.0)
    return r
